-- Keep the internal access RPC unexposed; RLS calls a caller-bound helper.
create or replace function private.rb_media_room_access(p_stream_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select case when auth.uid() is null then false else public.rb_live_can_access(p_stream_id,auth.uid()) end $$;
revoke all on function private.rb_media_room_access(uuid) from public,anon;
grant execute on function private.rb_media_room_access(uuid) to authenticated;
alter policy live_chat_messages_public_read on public.live_chat_messages to authenticated using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public')) or private.rb_media_room_access(stream_id) or (select public.rb_is_admin(1))) and not coalesce(is_deleted,false));
alter policy live_reactions_public_read on public.live_reactions to authenticated using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public')) or private.rb_media_room_access(stream_id) or (select public.rb_is_admin(1))));
alter policy live_member_activity_public_read on public.live_member_activity to authenticated using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public')) or private.rb_media_room_access(stream_id) or (select public.rb_is_admin(1))));
alter policy live_stream_members_public_read on public.live_stream_members to authenticated using ((exists (select 1 from public.live_streams s where s.id=stream_id and s.status='live' and coalesce(s.access_type,'free') in ('free','public')) or private.rb_media_room_access(stream_id) or (select public.rb_is_admin(1))));
